let CurrentSong=songs;
function loadTrack(index){
    track.src=CurrentSong[index].path;
    track.load();
    
    songName.innerText=CurrentSong[index].name;
    SongSinger.innerText=CurrentSong[index].singer;
    songImg.style.backgroundImage = `url('${CurrentSong[index].image}')`;

}

loadTrack(index);
function playSong(){
    track.play();
    gif.style.opacity=1;
     Play_pause.className="fa-solid fa-pause";
    playingSong=true;

}
function pauseSong(){
    track.pause();
    gif.style.opacity=0;
     Play_pause.className='fa-solid fa-play';
    playingSong=false;
}
Play_pause.addEventListener('click',()=>{
    if(playingSong==false)
    {
       
        playSong();
    }
    else{
       
        pauseSong();
    }
})
NextBtn.addEventListener('click',()=>{
    index = (index + 1) % songs.length;
    loadTrack(index);
    playSong();

})
previousBtn.addEventListener('click',()=>{
    index = (index - 1 + songs.length) % songs.length;
    loadTrack(index);
    playSong();
})
Volumerange.addEventListener("input", () => {
  const volume = Volumerange.value / 100;
  track.volume = Math.min(Math.max(volume, 0), 1);
});
document.addEventListener('keypress',(event)=>{
    if(event.key===' ')
    {
        Play_pause.click();
    }
})


SongDuration.addEventListener('input',()=>{
    track.currentTime=SongDuration.value;
})
function formatTime(time) {
  const min = Math.floor(time / 60);
  const sec = Math.floor(time % 60);
  return `${min}:${sec < 10 ? "0" : ""}${sec}`;
}

track.addEventListener("loadedmetadata", () => {
  SongDuration.max = track.duration;
  EndTime.innerText = formatTime(track.duration);
})
track.addEventListener("timeupdate", () => {
  SongDuration.value = track.currentTime;
   StartTime.innerText = formatTime(track.currentTime);
  
});
track.addEventListener("ended", () => {
  NextBtn.click();
});

let playList_img=document.querySelector('#playList_img');
let PlayList=document.querySelector('.PlayList');
playList_img.addEventListener('click',()=>{
    PlayList.classList.toggle('PlayList_active');
if(PlayList.classList.contains('PlayList_active'))
{
    playList_img.className="fa-solid fa-x";
    SearchSong.style.display='inline';
}
else{
    playList_img.className='fa-brands fa-playstation';
      SearchSong.style.display='none';
}



})


function SongLoad(songArray){

    CurrentSong = songArray;   // ⭐ important
    PlayList.innerHTML = '';

    songArray.forEach((obj, index) => {

        let ele = document.createElement('div');
        ele.className = 'PlayListSong';

        ele.innerHTML = `
            <img src="${obj.image}" alt="">
            <div class="songNameContainer">
                <h2>${obj.name}</h2>
                <h4>${obj.singer}</h4>
            </div>
        `;

        ele.addEventListener('click', () => {
            loadTrack(index);
            playSong();
        });

        PlayList.appendChild(ele);
    });
}

SongLoad(songs)

SearchSong.addEventListener('input', () => {
    let value = SearchSong.value.toLowerCase().trim();

    let NewArray = songs.filter(obj =>
    {

        return obj.name.toLowerCase().includes(value)||obj.singer.toLowerCase().includes(value);
    }
    );
   if (NewArray.length === 0) {
    PlayList.innerHTML = `
        <div class="notFound">
            Song Not Found
        </div>
    `;
    return;
}


    SongLoad(NewArray);
});
